#!/data/data/com.termux/files/usr/bin/bash
# ELAINA Optimasi - menu lebih rapi, RAM auto interval, kontak developer, pengatur animasi UI
# Extractor source project untuk Termux/GitHub Actions; tidak membangun APK secara lokal.
set -eu
PROJECT_DIR="${1:-ELAINA_Optimasi_Menu_Rapi}"
if [ -e "$PROJECT_DIR" ]; then
  echo "[ELAINA] Folder '$PROJECT_DIR' sudah ada; tidak menimpa file lama."
  echo "Jalankan dengan nama lain: bash setup_elaina_menu_rapi.sh ELAINA_baru"
  exit 1
fi
command -v base64 >/dev/null 2>&1 || { echo "base64 tidak ada. Termux: pkg install coreutils"; exit 1; }
command -v unzip >/dev/null 2>&1 || { echo "unzip tidak ada. Termux: pkg install unzip"; exit 1; }
mkdir -p "$PROJECT_DIR"
TMP_ZIP="$PROJECT_DIR/.elaina_source.zip"
cleanup() { rm -f "$TMP_ZIP"; }
trap cleanup EXIT
base64 -d > "$TMP_ZIP" <<'ELAINA_MENU_ZIP_EOF'
